__NUXT_JSONP__("/svet/stat/dominikanska-republika/videa", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n){return {data:[{tabsLoad:{tabWhatToSee:c,tabPrice:c,tabPeople:c,tabTrip:c,tabContact:c,tabHotel:c,tabNeighboring:d,tabVideos:e,tabArticles:e,tabWallSockets:h,tabChains:4,tabFauna:e,tabFlora:e,tabFoods:e,tabBrands:e},place:[{tld:".do",name:"Dominikánská republika",area:48670,population:10847904,slug:i,id_continent:d,information_chatgpt:"\u003Cp\u003EDominikánská republika, nebo také Dominika, je ostrovní stát nacházející se v Karibiku. S rozlohou více než 48 tisíc km² a více než 10 miliony obyvatel, je Dominikánská republika druhou největší zemí v Karibiku.\u003C\u002Fp\u003E\n\u003Cp\u003EStát je známý svými nádhernými plážemi, turistickými letovisky a tropickou přírodou, která zahrnuje horské pohoří, deštné pralesy a mnoho druhů rostlin a zvířat. V oblasti Punta Cana a Bavaro se nachází několik nejkrásnějších pláží na světě.\u003C\u002Fp\u003E\n\u003Cp\u003EDominikánská republika má také bohatou historii a kulturní dědictví. V minulosti byla kolonií Španělska, což se odráží v místní architektuře, kultuře a gastronomii. Na ostrově najdete mnoho historických památek, jako jsou starobylé kostely, kláštery a pevnosti.\u003C\u002Fp\u003E\n\u003Cp\u003EPro turisty nabízí Dominikánská republika mnoho aktivit, jako jsou potápění, šnorchlování, windsurfing, rybaření a golfové hřiště. Můžete si také vychutnat místní kuchyni, která je ovlivněna španělskou kuchyní, ale také karibskými a africkými tradicemi. Kromě toho je Dominikánská republika známá svým rumem, který se vyrábí z cukrové třtiny a je považován za jeden z nejlepších rumů na světě.\u003C\u002Fp\u003E\n\u003Cp\u003EV Dominikánské republice můžete navštívit mnoho malebných vesnic a měst, jako je například Santo Domingo, které bylo založeno již v roce 1498 a je nejstarším evropským městem v Americe. Santo Domingo je také místem, kde se nachází mnoho historických památek a muzeí.\u003C\u002Fp\u003E\n\u003Cp\u003EDominikánská republika je skvělým místem pro dovolenou, kde si můžete užít krásné pláže, přírodu, kulturu a dobrodružství. S přátelskými lidmi, skvělým jídlem a nádherným počasím bude vaše dovolená v Dominikánské republice nezapomenutelná.\u003C\u002Fp\u003E",money_prices:[{name:"Taxi (cena za km)",value:j,date_update:a},{name:"Hlavní jídlo",value:400,date_update:a},{name:"Chleba",value:30,date_update:a},{name:"Mléko",value:k,date_update:a},{name:"Voda (500ml)",value:j,date_update:a},{name:"Espresso",value:k,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:l,date_update:a},{name:"Pivo",value:80,date_update:a},{name:"Krabička cigaret",value:130,date_update:a},{name:"Bic Mac",value:b,date_update:a},{name:"Coca Cola (500ml)",value:l,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:a},{name:"Policie",value:f,date_update:a},{name:"Hasiči",value:f,date_update:a},{name:"Zdravotnická záchranná služba",value:f,date_update:a}],phone_prefix:"+1-809, +1-829, +1-849",coordinates:[{latitude:"18.7357",longitude:"-70.1627"}],people_religion:[{name:"Římskokatolická církev",value:"69.7%"},{name:"Evangelické církve",value:"18.4%"},{name:"Jiné náboženství",value:"10.2%"},{name:"Bez vyznání",value:"1.7%"}],people_nationality:[{name:"Dominikáni",value:"73.1%"},{name:"Haitiáni",value:m},{name:"Nerovnoměrně smíšené",value:"22.5%"},{name:"Jiné",value:m}],visitors_entry:[{name:"Občanský průkaz",value:"Občanský průkaz není platným cestovním dokladem pro vstup do Dominikánské republiky. Je nezbytné mít platný cestovní pas.",date_update:a},{name:"Cestovní pas",value:"Pro vstup do Dominikánské republiky je nezbytné mít platný cestovní pas.",date_update:a},{name:"Vízum",value:"Pro pobyt kratší než 90 dnů není pro občany ČR potřeba vízum. Při pobytu delším než 90 dnů je nutné žádat o vízum na Velvyslanectví Dominikánské republiky v Praze.",date_update:a},{name:"Očkování",value:"Při vstupu do Dominikánské republiky není vyžadováno očkování. Nicméně jsou doporučována očkování proti hepatitidě A a B a také vakcína proti žluté zimnici pro cestující z některých zemí.",date_update:a},{name:"Cestovní pojištění",value:"Při vstupu do Dominikánské republiky není vyžadováno cestovní nebo zdravotní pojištění. Nicméně se doporučuje mít pojištění, protože zdravotní péče v zemi může být poměrně drahá.",date_update:a},{name:"Bezpečnostní situace",value:"V Dominikánské republice existují určitá bezpečnostní rizika, zejména v oblasti kriminality a drog. Je důležité být obezřetný a dodržovat základní bezpečnostní opatření, jako je například ukládání cenností do hotelového sejfu a vyhýbání se nočním procházkám v neznámých oblastech. Doporučuje se také sledovat aktuální zpravodajství a konzultovat bezpečnostní rizika s cestovní kanceláří nebo velvyslanectvím.",date_update:a},{name:"Další informace",value:"Při návštěvě Dominikánské republiky je vhodné mít u sebe dostatek hotovosti, protože ne všechna zařízení přijímají platební karty. Místní obyvatelé jsou obvykle přátelští a přívětiví, ačkoli se mohou pokoušet nabízet turistům různé služby za poplatek. Je také důležité respektovat místní zvyklosti a kulturu.",date_update:a}],type_place:n,id_image_cover:g,id_image_hero:g,id_city_main:578,affiliate:[{name:"booking",value:c}],mpz:"DO",alerts:b,zoom:[{google:7,booking:8}],ids_neighboring_countries:[{id:99}],organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b,id:61,facts_place:b,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2024-03-04T19:48:12.84066+00:00",name_original:b,currency:[{code:"DOP",name:"dominikánské peso"}],setting_top:c,setting_status_public:d}],imagePlace:[{id:g,name:i,source:"\u002Fworld\u002Fstates\u002F",type:n,author:"pixabay.com",created_at:"2023-05-02T18:49:47.851894+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:d,slug:"severni-amerika",name:"Severní Amerika",area:24490000,population:589000000,population_density:24.04,number_states:23,information_chatgpt:"\u003Cp\u003ESeverní Amerika je třetím největším kontinentem na světě. Rozprostírá se od Arktického oceánu na severu až k Panama kanálu na jihu. Kontinent se skládá ze 23 nezávislých států, včetně Spojených států, Kanady a Mexika, a mnoha dalších závislých území, jako je Grónsko, Bermudy a Portoriko.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je známá svým pestrobarevným kulturním dědictvím, od původních obyvatel až po evropské osadníky a africké otroky. To se odráží v různorodosti jazyků, náboženství, kuchyně, hudby a tradic, které se na kontinentu nacházejí. \u003C\u002Fp\u003E\n\u003Cp\u003EMezi největší atrakce Severní Ameriky patří národní parky, jako jsou Yellowstone, Banff a Yosemite, které nabízejí ohromující přírodní krásy, jako jsou gejzíry, vodopády a divoká zvířata, včetně medvědů a losů. Mezi další populární turistické destinace patří města jako New York, San Francisco, Vancouver a Mexico City, která nabízejí různé zážitky a atrakce.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je také domovem mnoha kultur a tradic, včetně amerického fotbalu, baseballu a basketbalu, kanadského hokeje a mexického fotbalu. Navíc zde najdeme mnoho různých festivalů a oslav, jako například Día de los Muertos v Mexiku nebo Thanksgiving Day v USA a Kanadě.\u003C\u002Fp\u003E\n\u003Cp\u003EV západní části kontinentu najdeme nejvyšší horu Severní Ameriky, Mount McKinley, která se nachází v Aljašce. Východní část kontinentu pak tvoří rozsáhlé planiny, jako jsou Velká pláň a Floridská pláň. \u003C\u002Fp\u003E\n\u003Cp\u003EKlima Severní Ameriky se výrazně liší podle oblastí. Na severu a v oblastech vysokohorských pásem se vyskytují chladné a sněhové zimy, zatímco na jihu a na pobřeží Pacifiku jsou zimy mírnější. Celkově však kontinent nabízí mnoho slunečných a teplých dnů, zejména v letních měsících.\u003C\u002Fp\u003E\n\u003Cp\u003ENa kontinentu najdeme také mnoho různých druhů fauny a flóry. Mezi nejvíce známé zvířata patří medvědi, vlci, losi, bizoni, krokodýli a mnoho dalších. Severní Amerika má také rozmanitou flóru, včetně různých druhů stromů, květin a rostlin, jako jsou kaktusy a douglasky.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika má významnou roli ve světové ekonomice. Spojené státy jsou největší ekonomikou na světě, zatímco Kanada je jedním z největších světových výrobců surovin, jako je dřevo, zemní plyn a ropa. Mexiko je důležitým producentem automobilů, elektroniky a potravin. \u003C\u002Fp\u003E\n\u003Cp\u003ENavzdory tomu má Severní Amerika také mnoho výzev. Mezi největší problémy patří změna klimatu, nerovnost, přistěhovalectví a ochrana přírodních zdrojů. Zároveň však existuje mnoho iniciativ a organizací, které se snaží tyto problémy řešit a posilovat spolupráci mezi jednotlivými zeměmi kontinentu. \u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je fascinujícím kontinentem s mnoha přírodními krásami, kulturními tradicemi a ekonomickým vlivem na světovou scénu. Bez ohledu na to, zda se jedná o turistickou destinaci nebo oblast zájmu z hlediska vědy a průmyslu, Severní Amerika nabízí mnoho možností pro objevování a poznávání. \u003C\u002Fp\u003E",coordinates:[{latitude:47.497912,longitude:-100.540235}],type_place:"continent",id_image_cover:d,id_image_hero:d,zoom:[{google:h,booking:3}],information_author:b,seo_tags:b,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2024-03-04T19:48:06.634661+00:00",name_original:b,setting_top:c,setting_status_public:d}]}],fetch:{},mutations:[]}}("05-2023",null,true,1,0,"911",236,2,"dominikanska-republika",25,60,40,"2.2%","state")));